SELECT b.board_id AS boardId, b.title, b.content, b.restaurant_id AS restaurantId, r.restaurant_name AS restaurantName, b.board_img AS boardImg, b.board_tag AS boardTag, b.created_at AS createdAt, b.updated_at AS updatedAt, b.user_no AS userNo, u.nickname AS nickName, u.user_img AS userImg, (SELECT COUNT(*) FROM sns_like WHERE board_id = b.board_id) AS likeCount, (SELECT COUNT(*) FROM sns_comment WHERE board_id = b.board_id) AS commentCount, EXISTS( SELECT 1 FROM sns_like WHERE board_id = b.board_id AND user_no = #{myUserNo} ) AS isLiked FROM sns_board b INNER JOIN user u ON b.user_no = u.user_no LEFT JOIN restaurants r ON b.restaurant_id = r.restaurant_id WHERE b.user_no IN
#{userId}
ORDER BY b.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT b.board_id AS boardId, b.title, b.content, r.restaurant_name AS restaurantName, b.restaurant_id AS restaurantId, b.board_img AS boardImg, b.board_tag AS boardTag, b.created_at AS createdAt, b.updated_at AS updatedAt, b.user_no AS userNo, u.nickname AS nickName, u.user_img AS userImg, (SELECT COUNT(*) FROM sns_like WHERE board_id = b.board_id) AS likeCount, (SELECT COUNT(*) FROM sns_comment WHERE board_id = b.board_id) AS commentCount, EXISTS( SELECT 1 FROM sns_like WHERE board_id = b.board_id AND user_no = #{myUserNo} ) AS isLiked FROM sns_board b INNER JOIN user u ON b.user_no = u.user_no LEFT JOIN restaurants r ON b.restaurant_id = r.restaurant_id
b.user_no != #{myUserNo}
ORDER BY RAND() LIMIT #{limit}

SELECT menu_rating
FROM sns_board_image
WHERE image_id = #{imageId}

mapper.update:
UPDATE sns_board_image
SET
    menu_rating = #{snsBoardImageUpdateReq.menuRating},
    one_line_review = #{snsBoardImageUpdateReq.oneLineReview},
    image_url = #{snsBoardImageUpdateReq.imageUrl} 
WHERE image_id = #{snsBoardImageUpdateReq.imageId}

UPDATE menu
SET
    total_rating = COALESCE(total_rating, 0) + #{diff}
WHERE menu_id = #{menuId}

UPDATE restaurants
SET
    total_rating = COALESCE(total_rating, 0)   + #{totalDiff}
WHERE restaurant_id = #{restaurantId}
